use traffic::TrafficLight;

#[test]
fn test_initial_state() {
    let light = TrafficLight::new();
    assert_eq!(light.state(), "Red");
}

#[test]
fn test_transitions() {
    let mut light = TrafficLight::new();
    light.next();
    assert_eq!(light.state(), "Green");
    light.next();
    assert_eq!(light.state(), "Yellow");
    light.next();
    assert_eq!(light.state(), "Red");
}

#[test]
fn test_duration() {
    let mut light = TrafficLight::new(); // Red
    assert_eq!(light.duration_secs(), 30);
    light.next(); // Green
    assert_eq!(light.duration_secs(), 25);
    light.next(); // Yellow
    assert_eq!(light.duration_secs(), 5);
}

#[test]
fn test_is_stop() {
    let mut light = TrafficLight::new();
    assert!(light.is_stop());
    light.next();
    assert!(!light.is_stop());
    light.next();
    assert!(!light.is_stop());
}

#[test]
fn test_cycle_full() {
    let mut light = TrafficLight::new();
    let states: Vec<String> = (0..6).map(|_| { let s = light.state().to_string(); light.next(); s }).collect();
    assert_eq!(states, vec!["Red", "Green", "Yellow", "Red", "Green", "Yellow"]);
}

